const snippet = { id: 's1', kind: 'snippet', label: 'From the transcript', text: 'first line\nsecond line', status: 'ready' };
const element = { id: 'e1', kind: 'elementContext', status: 'ready', context: { tagName: 'button', id: 'save', classes: ['primary'],
  attributes: {}, computedStyles: {}, boundingBox: { x: 0, y: 0, width: 10, height: 10 }, innerText: 'Save', parentPath: 'main > button#save', outerHTML: '<button id="save">Save</button>' } };
