test('generated (3.6556.2): the tiles, the wrappers, lx, and the route are the original bindings with their official export aliases', () => {
  // code-composer is 3.6556.2 (w2-composer-gen §2.1): c0fbbe82d-COsmfHJY's wrappers Vi/Ui/Wi/Hi (Image/File/Quote/Video),
  // Co (the video MIME test), Bi (tile attributes, old mr), Ri (old pr), Ii (old dr); shared-2-TF8v67kg
  // `th=Object.assign(eh,{Image:Im,Video:Um,File:qm,Quote:$m})` exported as ry (old Hp/zg), the attachment attributes
  // wp/Tp/jp/Vp exported as iy/oy/ay/cy (old hf/gf/Sf/jf → Bg/Hg/Vg/Wg).
  const v3 = path.resolve(app, '../reference/snapshots/claude-3.6556.2-20261025-192807/ion-dist/assets/v1');
  const official3 = (name) => fs.readFileSync(path.join(v3, name), 'utf8');
  const tiles3 = official3('c0fbbe82d-COsmfHJY.js'), shared2v3 = official3('shared-2-TF8v67kg.js');
  for (const needle of ['function Vi(', 'function Ui(', 'function Wi(', 'function Hi(', 'function Bi(', 'function Ri(', 'function Ii(', ',Co=/^video\\/[a-z0-9.-]+$/;',
    'import{ay as $e,cy as et,iy as tt,ly as nt,oy as rt,ry as it}from"./shared-2-TF8v67kg.js"']) assert.equal(count(tiles3, needle), 1, needle);
  for (const needle of ['th=Object.assign(eh,{Image:Im,Video:Um,File:qm,Quote:$m})', 'th as ry', 'wp as iy', 'Tp as oy', 'jp as ay', 'Vp as cy'])
    assert.equal(count(shared2v3, needle), 1, needle);
  assert.equal(count(official3('shared-18-D3y8YMFN.js'), 'naturalImageTiles:"sized"'), 1);
  const manifest = JSON.parse(fs.readFileSync(path.join(app, 'src/generated/code-composer/manifest.json'), 'utf8'));
  assert.equal(manifest.referenceVersion, '3.6556.2');
  const byTarget = Object.fromEntries(manifest.modules.map((m) => [m.target, m]));
  assert.equal(byTarget['composer-attachment-tiles.mjs'].source, 'c0fbbe82d-COsmfHJY.js');
  assert.deepEqual(byTarget['composer-attachment-tiles.mjs'].bindings.map((b) => b.name), ['Ii', 'Li', 'Ri', 'zi', 'Bi', 'Vi', 'Hi', 'Ui', 'Wi', 'Co']);
  assert.equal(byTarget['chat-composer-attachments.mjs'].source, 'shared-2-TF8v67kg.js');
  for (const local of ['Im', 'Um', 'qm', '$m', 'eh', 'wp', 'Tp', 'jp', 'Vp']) assert.ok(byTarget['chat-composer-attachments.mjs'].bindings.some((b) => b.name === local), local);
  assert.ok(!byTarget['chat-composer-attachments.mjs'].bindings.some((b) => b.name === 'th'), 'no Object.assign on eh');
  assert.deepEqual(byTarget['composer-object-url.mjs'].officialExports, { ME: 'ha' });
  assert.deepEqual(byTarget['composer-video-types.mjs'].officialExports, { iN: 'rr' });
  assert.ok(byTarget['composer-attachment-tiles.mjs'].imports.some((i) => i.via === 'shared-7-DBAgAi5H.js:ha' && i.name === 'useFileObjectUrl' && i.kind === 'generated'));
  assert.ok(byTarget['composer-attachment-tiles.mjs'].imports.some((i) => i.via === 'shared-2-TF8v67kg.js:ry' && i.name === 'ComposerAttachmentTiles' && i.kind === 'adapter'));
  // The failed strip's Retry is view-tabs CdsTextLink (no stand-in), the Video tile's platform view-tabs useCdsPlatform.
  const attachmentImports = byTarget['chat-composer-attachments.mjs'].imports;
  assert.ok(attachmentImports.some((i) => i.via === 'shared-frame-6jtSkIit.js:hu' && i.name === 'CdsTextLink' && i.kind === 'view-tabs'));
  assert.ok(attachmentImports.some((i) => i.via === 'shared-frame-6jtSkIit.js:Pd' && i.name === 'useCdsPlatform' && i.kind === 'view-tabs'));
  assert.ok(!attachmentImports.some((i) => i.kind === 'adapter'), 'no adapter left in the tiles module');
  assert.ok(!fs.existsSync(path.join(app, 'src/source-composer-tile-retry-adapter.jsx')), 'the refusing retry stand-in is gone');
  assert.deepEqual(Object.fromEntries(['wp', 'Tp', 'jp', 'Vp'].map((k) => [k, byTarget['chat-composer-attachments.mjs'].officialExports[k]])), { wp: 'iy', Tp: 'oy', jp: 'ay', Vp: 'cy' });
  assert.deepEqual(byTarget['code-pane-experimental.mjs'].officialExports, { lx: 'Xd' });
  assert.deepEqual(byTarget['composer-intake-split.mjs'].officialExports, { nP: 'oc', pb: 'Tp' });
  assert.deepEqual(byTarget['composer-image-types.mjs'].officialExports, { a: 'i' });
  assert.deepEqual(byTarget['composer-intake-route.mjs'].bindings.map((b) => b.name), ['Kq']);
  assert.deepEqual(Experimental.codePaneExperimental, { naturalImageTiles: 'sized' });
  // The tile set adapter is all four of Hp's members (R4i-graph GR3 added Video).
  assert.deepEqual(TileAdapters.ComposerAttachmentTiles, { Image: Attachments.AttachmentImage, Video: Attachments.AttachmentVideo, File: Attachments.AttachmentFile, Quote: Attachments.AttachmentQuote });
  assert.equal(Attachments.MessageAttachments.Image, undefined, 'eh is not mutated');
  // Vi's video branch: a File-backed, video-named, video-typed attachment only.
  assert.ok(VideoTypes.videoFileNamePattern.test('clip.MOV') && !VideoTypes.videoFileNamePattern.test('clip.mkv'));
  assert.ok(Wrappers.videoMimeTypePattern.test('video/mp4') && !Wrappers.videoMimeTypePattern.test('image/png'));
  assert.equal(Tiles.isVideoTileEntry({ kind: 'file', name: 'clip.mp4', path: '/p/clip.mp4' }), false, 'a host entry keeps no File');
  assert.equal(Tiles.isVideoTileEntry({ kind: 'file', name: 'clip.mp4', file: { type: 'video/mp4' } }), true);
  assert.equal(Tiles.isVideoTileEntry({ kind: 'file', name: 'clip.mp4', file: { type: 'application/octet-stream' } }), false);
  assert.equal(Tiles.isVideoTileEntry({ kind: 'file', name: 'notes.txt', file: { type: 'video/mp4' } }), false);
  // Route: aK's lanes and answer (images by MIME only; otherFiles / folders lanes when given).
  const calls = [];
  const lanes = { images: (f) => calls.push(['images', f.map((x) => x.name)]), otherFiles: (f) => calls.push(['other', f.map((x) => x.name)]), folders: (f) => calls.push(['folders', f.map((x) => x.name)]) };
  assert.equal(Route.routeComposerIntake({ files: [{ name: 'a.png', type: 'image/png' }, { name: 'b.txt', type: 'text/plain' }], folders: [{ name: 'src', type: '' }] }, lanes), true);
  assert.deepEqual(calls, [['images', ['a.png']], ['other', ['b.txt']], ['folders', ['src']]]);
  assert.equal(Route.routeComposerIntake({ files: [], folders: [{ name: 'src' }] }, { images: noop, otherFiles: noop }), false, 'no folders lane: nothing taken');
  const item = (file, isDirectory = false) => ({ kind: 'file', getAsFile: () => file, webkitGetAsEntry: () => ({ isDirectory }) });
  const dir = { name: 'src' }, txt = { name: 'b.txt' };
  assert.deepEqual(Split.splitTransferItems([item(dir, true), item(txt), { kind: 'string', getAsFile: () => null }], []), { folders: [dir], files: [txt] });
});

// ---------------------------------------------------------------- the row (SSR)
test("SSR: Ri's row in uM's shelf — image tiles, file / folder tiles, quote tiles, then the pill group; official CDS markup", () => {
  const html = renderToStaticMarkup(inRoot(h(Tiles.ComposerAttachmentTiles, { entries: [image, pending, notes, folder, snippet, element], contextPills: [agent], onRemove: noop, onOpenFile: noop })));
  const root = tree(html)[0];
  const row = kids(root)[0];
  assert.equal(cls(row), Tiles.TILE_ROW_CLASS);
  assert.equal(Tiles.TILE_ROW_CLASS, 'flex flex-wrap items-end gap-xs');
  const order = kids(row).map((n) => n.attrs['data-cds'] ?? (n.attrs.role === 'status' ? 'status' : cls(n)));
  assert.deepEqual(order, ['MessageAttachmentsImage', 'MessageAttachmentsImage', 'status', 'MessageAttachmentsFile', 'MessageAttachmentsFile', 'MessageAttachmentsQuote', Tiles.PILL_ROW_CLASS]);
  const [ready, loading, status, file, dirTile, quote, pills] = kids(row);
  // hr: a ready image is a zoomable CardLink over the preview; a loading one is pending, with the Skeleton and the status.
  assert.equal(ready.attrs['data-cds-attachment'], '');
  assert.match(ready.attrs.style, /^--cds-attachment-vt-name:cds-attachment-/);
  assert.ok(find(ready.children, (n) => n.tag === 'img' && n.attrs.src === 'blob:shot'));
  assert.ok(cls(find(ready.children, (n) => n.attrs['data-cds'] === 'CardLink')).includes('cursor-zoom-in'));
  assert.equal(loading.attrs['data-state'], 'pending');
  assert.equal(find(loading.children, (n) => n.tag === 'img').attrs.src, undefined, 'no src before the preview exists');
  assert.ok(find(loading.children, (n) => n.attrs['data-cds'] === 'Skeleton'));
  assert.equal(find(loading.children, (n) => n.attrs['data-cds'] === 'CardLink'), null, 'pending: no press');
  assert.equal(status.text, 'Processing image');
  // _r: the extension badge, "Folder" for a directory; the path hover card makes the tile a tooltip trigger.
  const badge = (tile) => find(find(tile.children, (n) => n.attrs['data-cds'] === 'Badge').children, (n) => n.tag === 'bdi').text;
  assert.equal(badge(file), 'TXT');
  assert.equal(badge(dirTile), 'Folder');
  assert.equal(file.attrs['data-base-ui-tooltip-trigger'], '', 'Dt → the path tooltip trigger');
  assert.equal(ready.attrs['data-base-ui-tooltip-trigger'], undefined, 'Bi passes no filePath');
  // vr: the label as name, the text in the blockquote, the "Excerpt" badge with the label as its tooltip.
  assert.equal(find(quote.children, (n) => n.tag === 'blockquote').text, 'first line second line');
  assert.equal(badge(quote), 'Excerpt');
  assert.ok(find(quote.children, (n) => n.attrs['aria-label'] === 'Remove From the transcript'));
  // Ri's pill group: the agent pill, then the element context, both Go's ko (w12 preview-cont), no host shells.
  assert.deepEqual(kids(pills).map((n) => cls(n)), Array(2).fill('group/pill relative shrink-0 hover:z-10 focus-within:z-10'));
  assert.ok(find(kids(pills)[0].children, (n) => n.attrs['aria-label'] === 'Remove Reviewer'));
  assert.equal(find(pills.children, (n) => cls(n).includes('sca-pill')), null);
  assert.equal(renderToStaticMarkup(h(Tiles.ComposerAttachmentTiles, { entries: [] })), '', 'nothing staged: nothing rendered');
});

test('SSR: each tile is the generated wrapper with the props Bi / Vi / Hi give it (Ki / qi, the upper-case badge)', () => {
  const only = (entry) => renderToStaticMarkup(inRoot(h(Tiles.ComposerAttachmentTiles, { entries: [entry], onRemove: noop, onOpenFile: noop })));
  const wrap = (tile) => renderToStaticMarkup(inRoot(h('div', { className: Tiles.TILE_ROW_CLASS }, tile)));
  const ids = (html) => html.replace(/_R_[A-Za-z0-9]+_/g, 'ID');
  assert.equal(ids(only(notes)), ids(wrap(h(Wrappers.ComposerFileTile, { name: 'notes.txt', fileName: 'notes.txt', isDirectory: false, onOpen: noop, onRemove: noop, filePath: '/w/notes.txt' }))));
  assert.equal(ids(only({ ...notes, relativePath: 'docs/notes.txt' })), ids(wrap(h(Wrappers.ComposerFileTile, { name: 'docs/notes.txt', fileName: 'notes.txt', isDirectory: false, onOpen: noop, onRemove: noop, filePath: '/w/notes.txt' }))));
  assert.equal(ids(only(image)), ids(wrap(h(Wrappers.ComposerImageTile, { src: 'blob:shot', name: 'shot.png', pending: false, onOpen: noop, onRemove: noop }))));
  assert.equal(ids(only(snippet)), ids(wrap(h(Wrappers.ComposerQuoteTile, { name: snippet.label, text: snippet.text, badge: 'Excerpt', badgeTooltip: snippet.label, onOpen: noop, onRemove: noop }))));
});

test('every class the tiles and the row draw is in the loaded official sheets', () => {
  const sheets = ['shared-frame-CegduNQ2.css', 'shared-styles-D_GJawPO.css', 'c6a992d55-Che1orl5.css', 'c8e31bf58-C7gq8dUF.css', 'c3fde7009-BszyXGym.css']
    .map((f) => fs.readFileSync(path.join(app, 'public/assets/v1', f), 'utf8')).join('\n');
  const html = renderToStaticMarkup(inRoot(h(Tiles.ComposerAttachmentTiles, { entries: [image, pending, notes, folder, snippet], onRemove: noop, onOpenFile: noop })));
  const tokens = new Set();
  (function walk(nodes) { for (const n of nodes) { for (const t of cls(n).split(/\s+/)) if (t) tokens.add(t.replaceAll('&amp;', '&')); walk(kids(n)); } })(tree(html));
  assert.ok(tokens.size > 60, String(tokens.size));
  const escape = (token) => '.' + token.replace(/[^a-zA-Z0-9_-]/g, (c) => '\\' + c);
  // group/tile and group/card are group markers (no rule of their own); cds-root / contents come from CdsRoot.
  // 3.6556.2 CdsBadge also writes the fizzy-lake `stacks:` variant (shared-frame-6jtSkIit, e.g.
  // `stacks:rounded-[calc(var(--cds-h-control-nested)/2)]`); fizzy-lake is off (E12, Qm=[]) and no official 3.6556.2 sheet
  // carries a single `stacks:` rule, so those tokens are unstyled in the official app too.
  assert.equal(sheets.includes('.stacks\\:'), false, 'no official stacks: rule');
  const unstyled = [...tokens].filter((t) => !['group/tile', 'group/card'].includes(t)
    && !['{', ':', ',', '[', ' ', '>', ')', '.'].some((next) => sheets.includes(escape(t) + next)));
  assert.deepEqual(unstyled.filter((t) => !t.startsWith('stacks:')), []);
});

// ---------------------------------------------------------------- the presses (hook dispatcher)
function hookFixture(component) {
  let cursor = 0, dirty = false, result;
  const cells = [];
  const same = (a, b) => a && b && a.length === b.length && a.every((v, i) => Object.is(v, b[i]));
  const hooks = {
    useState(initial) { const i = cursor++; cells[i] ??= { value: typeof initial === 'function' ? initial() : initial }; return [cells[i].value, cells[i].set ??= (v) => { const next = typeof v === 'function' ? v(cells[i].value) : v; if (!Object.is(next, cells[i].value)) { cells[i].value = next; dirty = true; } }]; },
    useRef(initial) { const i = cursor++; cells[i] ??= { value: { current: initial } }; return cells[i].value; },
    useMemo(fn, deps) { const i = cursor++; if (!cells[i] || !same(cells[i].deps, deps)) cells[i] = { value: fn(), deps }; return cells[i].value; },
    useCallback(fn, deps) { return hooks.useMemo(() => fn, deps); },
    useContext(context) { return context._currentValue; },
    useId() { const i = cursor++; cells[i] ??= { value: `:r${i}:` }; return cells[i].value; },
    useEffect() {}, useLayoutEffect() {},
  };
  const render = (...args) => {
    const internal = React.__CLIENT_INTERNALS_DO_NOT_USE_OR_WARN_USERS_THEY_CANNOT_UPGRADE, old = internal.H;
    for (let pass = 0; pass < 8; pass++) {
      dirty = false; cursor = 0; internal.H = withMemoCache(hooks);
      try { result = component(...args); } finally { internal.H = old; }
      if (!dirty) break;
    }
    return result;
  };
  return { render };
}
const elements = (node, out = []) => {
  if (Array.isArray(node)) { for (const n of node) elements(n, out); return out; }
  if (!node || typeof node !== 'object' || !node.props) return out;
  out.push(node); elements(node.props.children, out); return out;
};

test('presses: an image opens the viewer from its tile, a file / folder opens / reveals, a snippet pins its preview; removal waits while sending', () => {
  const opened = [], removed = [];
  const props = { entries: [image, pending, notes, folder, snippet], contextPills: [], onRemove: (id) => removed.push(id), onOpenFile: (entry, action) => opened.push([entry.id, action]) };
  const fixture = hookFixture(Tiles.ComposerAttachmentTiles);
  const of = (tree, type) => elements(tree).filter((e) => e.type === type);
  let out = fixture.render(props);
  const [readyTile, loadingTile] = of(out, Wrappers.ComposerImageTile);
  assert.equal(loadingTile.props.pending, true);
  assert.equal(loadingTile.props.src, undefined);
  const img = { id: 'img' }, tile = { id: 'tile' };
  readyTile.props.onOpen(img, tile);
  out = fixture.render(props);
  const viewer = of(out, Viewer.SourceImageViewer)[0];
  assert.deepEqual([viewer.props.src, viewer.props.alt, viewer.props.originRef.current], ['blob:shot', 'shot.png', img]);
  viewer.props.onClose();
  out = fixture.render(props);
  assert.equal(of(out, Viewer.SourceImageViewer).length, 0);
  loadingTile.props.onOpen(null, tile);
  assert.equal(of(fixture.render(props), Viewer.SourceImageViewer).length, 0, 'a loading image does not open');
  const [fileTile, folderTile] = of(out, Wrappers.ComposerFileTile);
  assert.deepEqual([fileTile.props.name, fileTile.props.fileName, fileTile.props.isDirectory, fileTile.props.filePath], ['notes.txt', 'notes.txt', false, '/w/notes.txt']);
  fileTile.props.onOpen(null);
  folderTile.props.onOpen(null);
  assert.deepEqual(opened, [['f1', 'file'], ['d1', 'reveal']]);
  const quote = of(out, Wrappers.ComposerQuoteTile)[0];
  const anchor = { id: 'quote' };
  quote.props.onOpen({ currentTarget: anchor });
  out = fixture.render(props);
  const popover = of(out, Popover.SourcePopover)[0];
  assert.deepEqual([popover.props.anchor, popover.props.side, popover.props.align, popover.props.dataCds, popover.props.label], [anchor, 'top', 'start', 'AttachmentPreview', snippet.label]);
  assert.equal(elements(popover).find((e) => e.props.className === 'sca-preview-text').props.children, snippet.text);
  // A removed snippet closes its preview; removal goes to the host by id.
  for (const t of [readyTile, fileTile, quote]) t.props.onRemove();
  assert.deepEqual(removed, ['i1', 'f1', 's1']);
  assert.equal(of(fixture.render({ ...props, entries: [image] }), Popover.SourcePopover).length, 0);
  const sending = hookFixture(Tiles.ComposerAttachmentTiles);
  of(sending.render({ ...props, disabled: true }), Wrappers.ComposerFileTile)[0].props.onRemove();
  assert.deepEqual(removed, ['i1', 'f1', 's1'], 'held while the card sends');
  // Element context entries are SourceSelectedElementPill (ko), in Ri's pill group.
  const pills = of(fixture.render({ ...props, entries: [element] }), Elements.SourceSelectedElementPill);
  assert.equal(pills.length, 1);
});

test("Go's one strip intent: the pill group carries s / d / m, every pill gets the same intent, a move between pills switches at once", (t) => {
  const timers = new Map();
  let next = 1;
  const saved = Object.getOwnPropertyDescriptor(globalThis, 'window');
  Object.defineProperty(globalThis, 'window', { configurable: true, writable: true,
    value: { setTimeout: (fn, ms) => { timers.set(next, { fn, ms }); return next++; }, clearTimeout: (id) => timers.delete(id) } });
  t.after(() => { if (saved) Object.defineProperty(globalThis, 'window', saved); else delete globalThis.window; });
  const second = { ...element, id: 'e2' };
  const fixture = hookFixture(Tiles.ComposerAttachmentTiles);
  const props = { entries: [element, second], contextPills: [agent], onRemove: noop, onOpenFile: noop };
  const of = (tree, type) => elements(tree).filter((e) => e.type === type);
  const state = () => {
    const out = fixture.render(props);
    const group = elements(out).find((e) => e.props.className === Tiles.PILL_ROW_CLASS);
    const pills = [...of(out, Elements.SourceContextPill), ...of(out, Elements.SourceSelectedElementPill)];
    return { group, pills, intent: pills[0].props.intent };
  };
  let { group, pills, intent } = state();
  assert.equal(pills.length, 3);
  assert.ok(pills.every((p) => p.props.intent === intent), 'one intent for the whole strip');
  assert.deepEqual(['onMouseEnter', 'onMouseLeave', 'onBlur'].map((k) => typeof group.props[k]), ['function', 'function', 'function']);
  assert.equal(pills[1].props.anchorRef !== undefined && pills[2].props.anchorRef === undefined, true, 'ue anchors the first element pill');
  // Hover e1: opens after Go's 600 ms (fo).
  intent.onPreviewIntent('e1');
  assert.deepEqual([...timers.values()].map((x) => x.ms), [600]);
  [...timers.values()].forEach((x) => x.fn()); timers.clear();
  ({ intent } = state());
  assert.equal(intent.open, 'e1');
  // Move to e2: the strip's intent is already open, so it switches with no timer.
  intent.onPreviewIntent('e2');
  assert.equal(timers.size, 0);
  ({ intent } = state());
  assert.equal(intent.open, 'e2');
  // Leaving the strip (d = () => nn()) closes after Go's 200 ms (po).
  state().group.props.onMouseLeave();
  assert.deepEqual([...timers.values()].map((x) => x.ms), [200]);
  [...timers.values()].forEach((x) => x.fn()); timers.clear();
  assert.equal(state().intent.open, null);
});

test('the generated wrapper under a press: pr removes once per two frames and hands focus on; mr stamps the attachment attributes', (t) => {
  const frames = [];
  const saved = Object.getOwnPropertyDescriptor(globalThis, 'window');
  Object.defineProperty(globalThis, 'window', { value: { requestAnimationFrame: (fn) => frames.push(fn) }, configurable: true, writable: true });
  t.after(() => { if (saved) Object.defineProperty(globalThis, 'window', saved); else delete globalThis.window; });
  const removed = [];
  const fixture = hookFixture(Wrappers.ComposerFileTile);
  const out = fixture.render({ name: 'notes.txt', fileName: 'notes.txt', isDirectory: false, onOpen: noop, onRemove: () => removed.push('x'), filePath: '/w/notes.txt' });
  assert.equal(out.type, TileAdapters.ComposerPathHoverCard);
  assert.deepEqual([out.props.path, out.props.surface, out.props.attach], ['/w/notes.txt', 'composer', false]);
  const tileElement = out.props.trigger;
  assert.equal(tileElement.type, Attachments.AttachmentFile);
  assert.equal(tileElement.props.badge, 'TXT');
  assert.equal(tileElement.props['data-cds-attachment'], '');
  assert.equal(tileElement.props['data-cds-attachment-restored'], undefined);
  assert.match(tileElement.props.style['--cds-attachment-vt-name'], /^cds-attachment-/);
  tileElement.props.onRemove();
  tileElement.props.onRemove();
  assert.deepEqual(removed, ['x'], 'a second press inside the two frames is ignored');
  frames.splice(0).forEach((f) => f());
  frames.splice(0).forEach((f) => f());
  tileElement.props.onRemove();
  assert.deepEqual(removed, ['x', 'x']);
  // keepFocusOnPointerRemove: a mousedown on the remove button keeps focus where it is.
  let prevented = false;
  const button = { closest: () => button };
  tileElement.props.onMouseDown({ target: button, currentTarget: { contains: (n) => n === button }, preventDefault: () => { prevented = true; } });
  assert.equal(prevented, true);
  // The folder badge is the localized "Folder"; no path, no hover card trigger wrap.
  const dir = hookFixture(Wrappers.ComposerFileTile).render({ name: 'src', fileName: 'src', isDirectory: true, onRemove: noop });
  assert.equal(dir.props.trigger.props.badge, 'Folder');
  assert.equal(renderToStaticMarkup(h(TileAdapters.ComposerPathHoverCard, { trigger: h('i', null, 'x') })), '<i>x</i>');
});

